function pythagoreanTriplets(n) {
  const result = [];
  for (let a = 1; a <= n; a++) {
    for (let b = a; b <= n; b++) {
      const c = Math.sqrt(a * a + b * b);
      if (c === Math.floor(c) && c <= n) {
        result.push([a, b, c]);
      }
    }
  }
  return result;
}
